source='''from collections import Counter

def transform(grid):
    background = Counter(v for row in grid for v in row).most_common(1)[0][0]
    out = [row[:] for row in grid]
    for row in out:
        if row[0] == background:
            continue
        i = len(row)
        while i and row[i - 1] == background:
            i -= 1
        if i < len(row):
            row[i:] = [1] * (len(row) - i)
    return out
'''
